  1	import { message } from "../messages/index.ts";
  2	import { anonymityStatement, type QuestionData, parseRoundContext } from "./round-context.ts";
  3	
  4	declare global {
  5	  interface Window {
  6	    __sb_token?: string | undefined;
  7	    __sb_v?: number | undefined;
  8	    __sb_submitOrigin?: string | undefined;
  9	    __exchangePromise?: Promise<unknown> | undefined;
 10	  }
 11	}
 12	
 13	function getSubmitOrigin(): string {
 14	  if (typeof window.__sb_submitOrigin === "string" && window.__sb_submitOrigin.length > 0) {
 15	    return window.__sb_submitOrigin;
 16	  }
 17	  const host = window.location.hostname;
 18	  if (host === "app.surveybeat.app") {
 19	    return "https://submit.surveybeat.app";
 20	  }
 21	  if (host.endsWith(".app.surveybeat.app")) {
 22	    return `https://${host.replace(".app.surveybeat.app", ".submit.surveybeat.app")}`;
 23	  }
 24	  return window.location.origin;
 25	}
 26	
 27	function getStoredToken(): string {
 28	  const fromWindow = window.__sb_token;
 29	  if (typeof fromWindow === "string" && fromWindow.length > 0) {
 30	    return fromWindow;
 31	  }
 32	  const hash = window.location.hash;
 33	  if (hash.length > 1) {
 34	    const params = new URLSearchParams(hash.slice(1));
 35	    const t = params.get("t");
 36	    if (typeof t === "string" && t.length > 0) {
 37	      window.sessionStorage.setItem("sb_token", t);
 38	      return t;
 39	    }
 40	  }
 41	  const stored = window.sessionStorage.getItem("sb_token");
 42	  return typeof stored === "string" ? stored : "";
 43	}
 44	
 45	function generateEditKey(): string {
 46	  const bytes = new Uint8Array(32);
 47	  crypto.getRandomValues(bytes);
 48	  return Array.from(bytes, (byte) => byte.toString(16).padStart(2, "0")).join("");
 49	}
 50	
 51	async function sha256Hex(text: string): Promise<string> {
 52	  const data = new TextEncoder().encode(text);
 53	  const hash = await crypto.subtle.digest("SHA-256", data);
 54	  return Array.from(new Uint8Array(hash), (byte) => byte.toString(16).padStart(2, "0")).join("");
 55	}
 56	
 57	function mark(name: string): void {
 58	  if (typeof performance !== "undefined" && typeof performance.mark === "function") {
 59	    performance.mark(name);
 60	  }
 61	}
 62	
 63	async function postJson(url: string, body: unknown): Promise<unknown> {
 64	  const res = await fetch(url, {
 65	    method: "POST",
 66	    headers: { "content-type": "application/json" },
 67	    body: JSON.stringify(body),
 68	  });
 69	  if (!res.ok) {
 70	    const error = new Error(`HTTP ${res.status}`);
 71	    throw Object.assign(error, { status: res.status });
 72	  }
 73	  const data: unknown = await res.json();
 74	  return data;
 75	}
 76	
 77	function extractShownToLead(data: unknown): string | null {
 78	  if (
 79	    typeof data === "object" &&
 80	    data !== null &&
 81	    "shownToLead" in data &&
 82	    typeof data.shownToLead === "string"
 83	  ) {
 84	    return data.shownToLead;
 85	  }
 86	  return null;
 87	}
 88	
 89	function showError(msg: string): void {
 90	  const err = document.getElementById("err");
 91	  if (err instanceof HTMLElement) {
 92	    err.textContent = msg;
 93	    err.hidden = false;
 94	  }
 95	}
 96	
 97	function showStateMessage(msg: string): void {
 98	  const box = document.getElementById("state-message");
 99	  if (box instanceof HTMLElement) {
100	    box.className = "state-box";
101	    const p = document.createElement("p");
102	    p.textContent = msg;
103	    box.replaceChildren(p);
104	    box.hidden = false;
105	  }
106	  const s1 = document.getElementById("screen-1");
107	  if (s1 instanceof HTMLElement) {
108	    s1.hidden = true;
109	  }
110	  const rem = document.getElementById("remaining-screens");
111	  if (rem instanceof HTMLElement) {
112	    rem.hidden = true;
113	  }
114	  const thanks = document.getElementById("screen-thanks");
115	  if (thanks instanceof HTMLElement) {
116	    thanks.hidden = true;
117	  }
118	}
119	
120	type ScaleKey = "answer.scale.1" | "answer.scale.2" | "answer.scale.3" | "answer.scale.4" | "answer.scale.5";
121	
122	const scaleKeys: ReadonlyArray<ScaleKey> = [
123	  "answer.scale.1",
124	  "answer.scale.2",
125	  "answer.scale.3",
126	  "answer.scale.4",
127	  "answer.scale.5",
128	];
