130	async function run(): Promise<void> {
131	  document.title = message("answer.title");
132	
133	  const saveBtn = document.getElementById("save");
134	
135	  // Read preselected value
136	  let preselectedV = typeof window.__sb_v === "number" ? window.__sb_v : undefined;
137	  if (preselectedV === undefined && window.location.hash.length > 1) {
138	    const params = new URLSearchParams(window.location.hash.slice(1));
139	    const vParam = params.get("v");
140	    if (typeof vParam === "string") {
141	      const parsed = parseInt(vParam, 10);
142	      if (parsed >= 1 && parsed <= 5) {
143	        preselectedV = parsed;
144	      }
145	    }
146	  }
147	
148	  if (typeof preselectedV === "number") {
149	    const initialRadio = document.querySelector(`input[name="q1"][value="${preselectedV}"]`);
150	    if (initialRadio instanceof HTMLInputElement) {
151	      initialRadio.checked = true;
152	    }
153	  }
154	
155	  // Strip fragment so token does not linger in history (ADR 0005)
156	  if (window.location.hash.length > 0) {
157	    window.history.replaceState(null, "", window.location.pathname + window.location.search);
158	  }
159	
160	  const token = getStoredToken();
161	  const submitOrigin = getSubmitOrigin();
162	
163	  let exchangePromise = window.__exchangePromise;
164	  if (!exchangePromise) {
165	    if (token.length === 0) {
166	      showError(message("answer.error"));
167	      return;
168	    }
169	    exchangePromise = postJson(`${submitOrigin}/exchange`, { token });
170	  }
171	
172	  let rawContext: unknown;
173	  try {
174	    rawContext = await exchangePromise;
175	  } catch (err: unknown) {
176	    if (typeof err === "object" && err !== null && "status" in err && err.status === 404) {
177	      showError(message("answer.error"));
178	      return;
179	    }
180	    showError(message("answer.error"));
181	    return;
182	  }
183	
184	  const context = parseRoundContext(rawContext);
185	  if (context === null) {
186	    showError(message("answer.error"));
187	    return;
188	  }
189	
190	  // What the lead will and will not see needs the Team's N, so it waits for the context.
191	  const anonEl = document.getElementById("anon");
192	  if (anonEl instanceof HTMLElement) {
193	    anonEl.textContent = anonymityStatement(context);
194	  }
195	
196	  // Trigger dynamic schema validation after first paint (keeps Effect Schema off critical path)
197	  const scheduleValidation = () => {
198	    void import("./schema-validate.ts").then((mod) => {
199	      mod.validateRoundContext(rawContext);
200	    });
201	  };
202	  setTimeout(scheduleValidation, 8000);
203	
204	  // Check state
205	  if (context.state !== "open") {
206	    showStateMessage(message("answer.state.closed"));
207	    return;
208	  }
209	
210	  const roundStorageKey = `sb_edit_${context.roundId}`;
211	  let editKey = window.localStorage.getItem(roundStorageKey) ?? "";
212	
213	  if (context.hasAnswered) {
214	    if (editKey.length === 0) {
215	      showStateMessage(message("answer.state.otherBrowser"));
216	      return;
217	    }
218	    // Member has edit key on this device; proceed to allow editing/reviewing answers
219	  }
220	
221	  // Populate Screen 1
222	  const pulseEl = document.getElementById("pulse");
223	  if (pulseEl instanceof HTMLElement) {
224	    pulseEl.textContent = context.pulseName;
225	  }
226	
227	  const q1 = context.questions[0];
228	  if (q1) {
229	    const q1text = document.getElementById("q1text");
230	    if (q1text instanceof HTMLElement) {
231	      q1text.textContent = q1.text;
232	    }
233	  }
234	
235	  if (saveBtn instanceof HTMLButtonElement) {
236	    saveBtn.disabled = false;
237	  }
238	
239	  mark("meaningful");
240	
241	  let firstSaved = context.hasAnswered;
242	
243	  const doFirstSave = async (ratingVal: number): Promise<void> => {
244	    if (firstSaved) return;
245	    if (saveBtn instanceof HTMLButtonElement) {
246	      saveBtn.disabled = true;
247	    }
248	    mark("first-save-start");
249	    try {
250	      editKey = generateEditKey();
251	      const editKeyHash = await sha256Hex(editKey);
252	      window.localStorage.setItem(roundStorageKey, editKey);
253	
254	      await postJson(`${submitOrigin}/first-answer`, {
255	        token,
256	        editKeyHash,
257	        questionVersionId: q1 ? q1.id : "",
258	        value: ratingVal,
259	      });
260	
261	      firstSaved = true;
262	      // Invariant: after the first save, no request carries the token (ADR 0005)
263	      window.sessionStorage.removeItem("sb_token");
264	      window.__sb_token = undefined;
265	
266	      mark("first-save-end");
267	      mark("screen2");
268	      goToRemainingScreens();
269	    } catch (err: unknown) {
270	      if (typeof err === "object" && err !== null && "status" in err && err.status === 409) {
271	        showStateMessage(message("answer.state.alreadyAnswered"));
272	        return;
273	      }
274	      showError(message("answer.error"));
275	      if (saveBtn instanceof HTMLButtonElement) {
276	        saveBtn.disabled = false;
277	      }
278	    }
279	  };
280	
281	  // Screen 1 form submit
282	  const f1 = document.getElementById("f1");
283	  if (f1 instanceof HTMLFormElement) {
284	    f1.addEventListener("submit", (e) => {
285	      e.preventDefault();
286	      const checked = document.querySelector('input[name="q1"]:checked');
287	      if (checked instanceof HTMLInputElement) {
288	        void doFirstSave(Number(checked.value));
289	      }
290	    });
291	  }
292	
293	  // Value change on Screen 1 also confirms first save (ADR 0007)
294	  const q1Radios = document.querySelectorAll('input[name="q1"]');
295	  q1Radios.forEach((r) => {
296	    if (r instanceof HTMLInputElement) {
297	      r.addEventListener("change", () => {
298	        void doFirstSave(Number(r.value));
299	      });
300	    }
301	  });
302	
303	  const goToRemainingScreens = () => {
304	    const s1 = document.getElementById("screen-1");
305	    if (s1 instanceof HTMLElement) {
306	      s1.hidden = true;
307	    }
308	
309	    const remainingQuestions = context.questions.slice(1);
310	    if (remainingQuestions.length === 0) {
311	      goToThanksScreen();
312	      return;
313	    }
314	
315	    renderRemainingQuestions(remainingQuestions);
316	  };
317	
318	  const goToThanksScreen = () => {
319	    const s1 = document.getElementById("screen-1");
320	    if (s1 instanceof HTMLElement) {
321	      s1.hidden = true;
322	    }
323	    const rem = document.getElementById("remaining-screens");
324	    if (rem instanceof HTMLElement) {
325	      rem.hidden = true;
326	    }
327	
328	    const thanks = document.getElementById("screen-thanks");
329	    if (thanks instanceof HTMLElement) {
330	      thanks.hidden = false;
331	      const h2 = thanks.querySelector("h2");
332	      if (h2 instanceof HTMLElement) {
333	        h2.focus();
334	      }
335	    }
336	
337	    const bodyEl = document.getElementById("thanks-body");
338	    const actionsUl = document.getElementById("actions");
339	    if (context.actions.length > 0) {
340	      if (bodyEl instanceof HTMLElement) {
341	        bodyEl.textContent = message("answer.thanks.body");
342	      }
343	      if (actionsUl instanceof HTMLUListElement) {
344	        actionsUl.replaceChildren(
345	          ...context.actions.slice(0, 3).map((act) => {
346	            const li = document.createElement("li");
347	            li.textContent = act.title;
348	            return li;
349	          }),
350	        );
351	      }
352	    } else {
353	      if (bodyEl instanceof HTMLElement) {
354	        bodyEl.textContent = message("answer.thanks.bodyNoActions");
355	      }
356	      if (actionsUl instanceof HTMLElement) {
357	        actionsUl.replaceChildren();
358	      }
359	    }
360	  };
361	
362	  const renderRemainingQuestions = (questions: ReadonlyArray<QuestionData>) => {
363	    const container = document.getElementById("remaining-screens");
364	    if (!(container instanceof HTMLElement)) return;
365	
366	    container.hidden = false;
367	    container.replaceChildren();
368	
369	    const isDesktop = window.matchMedia("(min-width: 640px)").matches;
370	    document.body.classList.toggle("is-desktop", isDesktop);
371	
372	    const questionSections: Array<HTMLElement> = [];
373	
374	    questions.forEach((q, idx) => {
375	      const section = document.createElement("section");
376	      section.setAttribute("data-question-screen", String(idx + 2));
377	      section.className = "question-block";
378	      // On mobile, hide screens past the first remaining question
379	      if (!isDesktop && idx > 0) {
380	        section.hidden = true;
381	      }
382	
383	      const fieldset = document.createElement("fieldset");
384	      const legend = document.createElement("legend");
385	      legend.tabIndex = -1;
386	      legend.textContent = q.text;
387	      fieldset.appendChild(legend);
388	
389	      if (q.type._tag === "Rating") {
390	        const scaleDiv = document.createElement("div");
391	        scaleDiv.className = "scale";
392	        for (let i = 1; i <= 5; i++) {
393	          const lbl = document.createElement("label");
394	          const radio = document.createElement("input");
395	          radio.type = "radio";
396	          radio.name = `q_${q.id}`;
397	          radio.value = String(i);
398	
399	          radio.addEventListener("change", () => {
400	            void saveAnswer(q.id, { value: i });

   400	            void saveAnswer(q.id, { value: i });
   401	          });
   402	
   403	          const span = document.createElement("span");
   404	          const scaleKey = scaleKeys[i - 1];
   405	          if (scaleKey !== undefined) {
   406	            span.textContent = `${i} · ${message(scaleKey)}`;
   407	          }
   408	          lbl.appendChild(radio);
   409	          lbl.appendChild(span);
   410	          scaleDiv.appendChild(lbl);
   411	        }
   412	        fieldset.appendChild(scaleDiv);
   413	      } else if (q.type._tag === "SingleChoice") {
   414	        const scaleDiv = document.createElement("div");
   415	        scaleDiv.className = "scale";
   416	        q.type.options.forEach((opt, optIdx) => {
   417	          const lbl = document.createElement("label");
   418	          const radio = document.createElement("input");
   419	          radio.type = "radio";
   420	          radio.name = `q_${q.id}`;
   421	          radio.value = String(optIdx);
   422	
   423	          radio.addEventListener("change", () => {
   424	            void saveAnswer(q.id, { value: optIdx });
   425	          });
   426	
   427	          const span = document.createElement("span");
   428	          span.textContent = opt;
   429	          lbl.appendChild(radio);
   430	          lbl.appendChild(span);
   431	          scaleDiv.appendChild(lbl);
   432	        });
   433	        fieldset.appendChild(scaleDiv);
   434	      }
   435	
   436	      section.appendChild(fieldset);
   437	
   438	      // Comments: Rating with comment=true, or LongText
   439	      const hasComment = (q.type._tag === "Rating" && q.type.comment === true) || q.type._tag === "LongText";
   440	
   441	      if (hasComment) {
   442	        const commentDiv = document.createElement("div");
   443	        commentDiv.className = "comment-section";
   444	
   445	        const lbl = document.createElement("label");
   446	        lbl.htmlFor = `comment_${q.id}`;
   447	        lbl.className = "comment-label";
   448	        lbl.textContent = message("answer.comment.label");
   449	        commentDiv.appendChild(lbl);
   450	
   451	        const disclosure = document.createElement("p");
   452	        disclosure.className = "comment-disclosure";
   453	        disclosure.id = `disclosure_${q.id}`;
   454	        disclosure.textContent = message("answer.comment.disclosure");
   455	        commentDiv.appendChild(disclosure);
   456	
   457	        const textarea = document.createElement("textarea");
   458	        textarea.id = `comment_${q.id}`;
   459	        textarea.maxLength = 1000;
   460	        textarea.setAttribute("aria-describedby", `disclosure_${q.id}`);
   461	
   462	        const leadP = document.createElement("p");
   463	        leadP.className = "lead-preview";
   464	        leadP.setAttribute("aria-live", "polite");
   465	
   466	        const saveComment = async () => {
   467	          const val = textarea.value.trim();
   468	          if (val.length === 0) return;
   469	          try {
   470	            const raw = await saveAnswer(q.id, { comment: val });
   471	            const shownToLead = extractShownToLead(raw);
   472	            if (shownToLead !== null) {
   473	              leadP.textContent = message("answer.comment.leadSees", { text: shownToLead });
   474	            }
   475	          } catch {
   476	            showError(message("answer.error"));
   477	          }
   478	        };
   479	
   480	        textarea.addEventListener("change", () => {
   481	          void saveComment();
   482	        });
   483	        textarea.addEventListener("blur", () => {
   484	          void saveComment();
   485	        });
   486	
   487	        commentDiv.appendChild(textarea);
   488	        commentDiv.appendChild(leadP);
   489	        section.appendChild(commentDiv);
   490	      }
   491	
   492	      // Navigation buttons
   493	      const isLast = idx === questions.length - 1;
   494	      const nextBtn = document.createElement("button");
   495	      nextBtn.type = "button";
   496	      nextBtn.className = "mobile-next-btn";
   497	      nextBtn.textContent = isLast ? message("answer.finish") : message("answer.next");
   498	      nextBtn.addEventListener("click", () => {
   499	        if (isLast) {
   500	          goToThanksScreen();
   501	        } else {
   502	          section.hidden = true;
   503	          const nextSec = questionSections[idx + 1];
   504	          if (nextSec instanceof HTMLElement) {
   505	            nextSec.hidden = false;
   506	            const leg = nextSec.querySelector("legend");
   507	            if (leg instanceof HTMLElement) {
   508	              leg.focus();
   509	            }
   510	          }
   511	        }
   512	      });
   513	      section.appendChild(nextBtn);
   514	
   515	      questionSections.push(section);
   516	      container.appendChild(section);
   517	    });
   518	
   519	    // Desktop finish button
   520	    const finishBtn = document.createElement("button");
   521	    finishBtn.type = "button";
   522	    finishBtn.className = "desktop-finish-btn";
   523	    finishBtn.textContent = message("answer.finish");
   524	    finishBtn.addEventListener("click", () => {
   525	      goToThanksScreen();
   526	    });
   527	    container.appendChild(finishBtn);
   528	
   529	    // Focus the first remaining question legend
   530	    const firstLegend = questionSections[0]?.querySelector("legend");
   531	    if (firstLegend instanceof HTMLElement) {
   532	      firstLegend.focus();
   533	    }
   534	  };
   535	
   536	  const saveAnswer = async (
   537	    questionVersionId: string,
   538	    body: { value?: number; comment?: string },
   539	  ): Promise<unknown> => {
   540	    mark("answer-save-start");
   541	    // Invariant: Subsequent answers carry editKey, NEVER token (ADR 0005)
   542	    const result = await postJson(`${submitOrigin}/answer`, {
   543	      editKey,
   544	      questionVersionId,
   545	      ...body,
   546	    });
   547	    mark("answer-save-end");
   548	    return result;
   549	  };
   550	}
   551	
   552	void run();
