     1	import { message } from "../messages/index.ts";
     2	
     3	export interface QuestionTypeRating {
     4	  readonly _tag: "Rating";
     5	  readonly lowLabel?: string;
     6	  readonly highLabel?: string;
     7	  readonly comment?: boolean;
     8	}
     9	
    10	export interface QuestionTypeSingleChoice {
    11	  readonly _tag: "SingleChoice";
    12	  readonly options: ReadonlyArray<string>;
    13	}
    14	
    15	export interface QuestionTypeLongText {
    16	  readonly _tag: "LongText";
    17	}
    18	
    19	export type QuestionType = QuestionTypeRating | QuestionTypeSingleChoice | QuestionTypeLongText;
    20	
    21	export interface QuestionData {
    22	  readonly id: string;
    23	  readonly position: number;
    24	  readonly text: string;
    25	  readonly type: QuestionType;
    26	}
    27	
    28	export interface ActionData {
    29	  readonly id: string;
    30	  readonly title: string;
    31	}
    32	
    33	export interface RoundContextData {
    34	  readonly roundId: string;
    35	  readonly pulseName: string;
    36	  readonly minimumGroupSize: number;
    37	  readonly questions: ReadonlyArray<QuestionData>;
    38	  readonly actions: ReadonlyArray<ActionData>;
    39	  readonly closeTime: number;
    40	  readonly state: string;
    41	  readonly hasAnswered: boolean;
    42	  readonly aiProcessing: boolean;
    43	}
    44	
    45	/**
    46	 * What the lead will and will not see (SPEC 5.2). When the Organization processes comments with AI, the
    47	 * answer page says so right after it (ADR 0015).
    48	 */
    49	export function anonymityStatement(context: RoundContextData): string {
    50	  const anonymity = message("answer.anonymity", { n: context.minimumGroupSize });
    51	  return context.aiProcessing ? `${anonymity} ${message("answer.aiNotice")}` : anonymity;
    52	}
    53	
    54	export function parseRoundContext(data: unknown): RoundContextData | null {
    55	  if (typeof data !== "object" || data === null) return null;
    56	  if (!("roundId" in data) || typeof data.roundId !== "string") return null;
    57	  if (!("pulseName" in data) || typeof data.pulseName !== "string") return null;
    58	  if (!("minimumGroupSize" in data) || typeof data.minimumGroupSize !== "number") return null;
    59	  if (!("closeTime" in data) || typeof data.closeTime !== "number") return null;
    60	  if (!("state" in data) || typeof data.state !== "string") return null;
    61	  if (!("hasAnswered" in data) || typeof data.hasAnswered !== "boolean") return null;
    62	  // Absent means off: the flag is new, and a context without it is a context for an Organization without AI processing.
    63	  const aiProcessing = "aiProcessing" in data && data.aiProcessing === true;
    64	  if (!("questions" in data) || !Array.isArray(data.questions)) return null;
    65	
    66	  const questions: Array<QuestionData> = [];
    67	  for (const item of data.questions) {
    68	    if (
    69	      typeof item === "object" &&
    70	      item !== null &&
    71	      "id" in item &&
    72	      typeof item.id === "string" &&
    73	      "text" in item &&
    74	      typeof item.text === "string" &&
    75	      "position" in item &&
    76	      typeof item.position === "number"
    77	    ) {
    78	      let qType: QuestionType = { _tag: "Rating", comment: true };
    79	      if ("type" in item && typeof item.type === "object" && item.type !== null && "_tag" in item.type) {
    80	        if (item.type._tag === "Rating") {
    81	          qType = {
    82	            _tag: "Rating",
    83	            lowLabel:
    84	              "lowLabel" in item.type && typeof item.type.lowLabel === "string"
    85	                ? item.type.lowLabel
    86	                : undefined,
    87	            highLabel:
    88	              "highLabel" in item.type && typeof item.type.highLabel === "string"
    89	                ? item.type.highLabel
    90	                : undefined,
    91	            comment:
    92	              "comment" in item.type && typeof item.type.comment === "boolean" ? item.type.comment : true,
