265	  if (overview.rounds.length !== 1) found.push(`overview has ${overview.rounds.length} rounds, expected 1`);
266	  for (const line of overview.dimensions) {
267	    const label = `overview ${line.dimension}`;
268	    const fresh = built.direct.dimensions.find((each) => each.dimension === line.dimension);
269	    const { usable, contributors } = dimensionContributors(built, line.dimension, n);
270	    for (const point of line.points) {
271	      if (point.score === null) continue;
