283	/** Every way the Result shows an aggregate that fewer than the effective N contributors stand behind. */
284	const violations = (scenario: RoundResultScenario, built: Built): ReadonlyArray<string> => {
285	  const { result, direct, effectiveN: n } = built;
286	  const found: Array<string> = [];
287	  const open = scenario.status === "open";
288	  const roundMeetsN = !open && result.submissionsCount >= n;
289	  if (result.submissionsCount !== scenario.submissions.length) found.push("submissionsCount differs");
290	
291	  if (!roundMeetsN && result.comments.length > 0) found.push("comments shown below N");
292	  if (roundMeetsN) {
293	    const raw = built.submissions
294	      .flatMap((submission) => submission.answers)
295	      .filter((a) => a.comment?.trim());
296	    if (result.comments.length > raw.length) found.push("more comments than the Submissions carry");
297	  }
298	
299	  const visibleScore = new Map<string, number>();
300	  result.questions.forEach((question, index) => {
301	    const label = `question ${index}`;
302	    const expected = contributorsOf(built, index);
303	    const shown = question.score !== null || question.distribution !== null;
304	    if (shown && !(roundMeetsN && expected >= n)) {
305	      found.push(`${label} shows an aggregate from ${expected} contributors (N=${n})`);
306	    }
307	    if (!shown && (question.change !== null || question.typicalChange !== null)) {
308	      found.push(`${label} shows a change or typical change without a visible score`);
309	    }
310	    if (question.score !== null) visibleScore.set(question.questionVersionId, question.score);
311	    for (const point of question.trend) {
312	      if (point.score !== null && point.contributors < n) {
313	        found.push(
314	          `${label} trend point ${point.roundId} shows a score from ${point.contributors} contributors`,
315	        );
316	      }
317	      if (point.roundId === ROUND && point.score !== null && !shown) {
318	        found.push(`${label} current trend point shows a score the Question hides`);
319	      }
320	    }
321	    // Never more than a fresh computation at the effective N would show, and never different.
322	    const fresh = direct.questions[index];
323	    if (
324	      shown &&
325	      (question.score !== fresh?.score ||
326	        !Object.is(JSON.stringify(question.distribution), JSON.stringify(fresh?.distribution)))
327	    ) {
328	      found.push(`${label} differs from the Result computed at N=${n}`);
329	    }
330	    if (question.change !== null && JSON.stringify(question.change) !== JSON.stringify(fresh?.change)) {
331	      found.push(`${label} change differs from the Result computed at N=${n}`);
332	    }
333	    if (
334	      question.typicalChange !== null &&
335	      JSON.stringify(question.typicalChange) !== JSON.stringify(fresh?.typicalChange)
336	    ) {
337	      found.push(`${label} typical change differs from the Result computed at N=${n}`);
338	    }
339	    question.trend.forEach((point, p) => {
340	      const freshPoint = fresh?.trend[p];
341	      if (point.score !== null && point.score !== freshPoint?.score) {
342	        found.push(`${label} trend point ${point.roundId} differs from the Result computed at N=${n}`);
343	      }
344	    });
345	  });
346	
347	  result.dimensions.forEach((dimension) => {
348	    const label = `dimension ${dimension.dimension}`;
349	    const { usable, contributors } = dimensionContributors(built, dimension.dimension, n);
350	    if (dimension.score === null) {
351	      if (dimension.contributors !== undefined && dimension.contributors !== null) {
352	        found.push(`${label} shows contributors without a score`);
353	      }
354	      if (dimension.change !== null || dimension.typicalChange !== null) {
355	        found.push(`${label} shows a change or typical change without a score`);
356	      }
357	    } else {
358	      if (usable.length === 0 || contributors < n) {
359	        found.push(`${label} shows a score from ${contributors} contributors (N=${n})`);
360	      }
361	      const scores = usable.map(({ question }) => visibleScore.get(question.id));
362	      if (scores.some((score) => score === undefined)) {
363	        found.push(`${label} is computed from a Question that is hidden`);
364	      } else {
365	        const mean = roundDecimals(
366	          scores.reduce<number>((sum, score) => sum + (score ?? 0), 0) / scores.length,
367	          2,
368	        );
369	        if (mean !== dimension.score)
370	          found.push(`${label} score ${dimension.score} is not the mean of the visible Questions ${mean}`);
371	      }
372	      if (
373	        dimension.contributors !== undefined &&
374	        dimension.contributors !== null &&
375	        dimension.contributors < n
376	      ) {
377	        found.push(`${label} reports ${dimension.contributors} contributors (N=${n})`);
378	      }
379	    }
380	    for (const point of dimension.trend) {
381	      if (point.score !== null && (point.contributors === undefined || point.contributors < n)) {
382	        found.push(
383	          `${label} trend point ${point.roundId} shows a score from ${point.contributors ?? "unknown"} contributors`,
384	        );
385	      }
386	    }
387	    const fresh = direct.dimensions.find((each) => each.dimension === dimension.dimension);
388	    if (dimension.score !== null && dimension.score !== fresh?.score) {
389	      found.push(`${label} differs from the Result computed at N=${n}`);
390	    }
391	    if (
392	      dimension.typicalChange !== null &&
393	      JSON.stringify(dimension.typicalChange) !== JSON.stringify(fresh?.typicalChange)
394	    ) {
395	      found.push(`${label} typical change differs from the Result computed at N=${n}`);
396	    }
397	    if (dimension.change !== null && JSON.stringify(dimension.change) !== JSON.stringify(fresh?.change)) {
398	      found.push(`${label} change differs from the Result computed at N=${n}`);
399	    }
400	  });
401	  return found;
402	};

