141	      past.submissionsCount >= contributors
142	        ? score
143	        : null;
144	    return {
145	      roundId: RoundId.make(`past-${i}`),
146	      plannedOpenDate: new Date(Date.UTC(2025, 0, 6 + 7 * i)).toISOString().slice(0, 10),
147	      closedAt: 1_700_000_000_000 + i,
148	      effectiveMinimumGroupSize: past.effectiveMinimumGroupSize,
149	      submissionsCount: past.submissionsCount,
150	      questions: questions.map((question, index) => {
151	        const slot = past.questions[index];
152	        const score = usable(slot?.score ?? null, slot?.contributors ?? 0);
153	        return {
154	          questionVersionId: question.id,
155	          score,
156	          contributors: slot?.contributors ?? 0,
157	          meetsMinimumGroupSize: score !== null,
