    61	 */
    62	export const buildTeamOverview = (params: {
    63	  readonly teamId: TeamId;
    64	  readonly results: ReadonlyArray<RoundResult>;
    65	  readonly minimumGroupSize: number;
    66	  readonly actions: ReadonlyArray<OverviewActionInput>;
    67	}): TeamOverview => {
    68	  const shared = params.results
    69	    .filter((result) => result.status === "shared")
    70	    .map((result) => enforceEffectiveNOnResult(result, params.minimumGroupSize))
    71	    .sort(
    72	      (a, b) => compareStrings(a.plannedOpenDate, b.plannedOpenDate) || compareStrings(a.roundId, b.roundId),
    73	    );
